scripts\\qingquan-client.ps1.content:
# 清泉中心 Ingest 客户端（Stage A 旁路）
# 由 run-multi-store.ps1 dot-source 使用；也可单独点测。
#
# 依赖 config.qingquan:
# {
#   "enabled": true,
#   "baseUrl": "http://127.0.0.1:8000",
#   "apiKey": "dev-ingest-key",
#   "source": "tiktok_ads",
#   "failOpen": true,
#   "timeoutSec": 30
# }

function Get-QingquanConfig($cfg) {
  if (-not $cfg.qingquan) {
    return [pscustomobject]@{
      enabled    = $false
      baseUrl    = 'http://127.0.0.1:8000'
      apiKey     = ''
      source     = 'tiktok_ads'
      failOpen   = $true
      timeoutSec = 30
    }
  }
  $q = $cfg.qingquan
  $enabled = $false
  if ($null -ne $q.enabled) { $enabled = [bool]$q.enabled }
  $failOpen = $true
  if ($null -ne $q.failOpen) { $failOpen = [bool]$q.failOpen }
  $timeout = 30
  if ($null -ne $q.timeoutSec) { $timeout = [int]$q.timeoutSec }
  $source = 'tiktok_ads'
  if ($q.source) { $source = [string]$q.source }
  $base = 'http://127.0.0.1:8000'
  if ($q.baseUrl) { $base = [string]$q.baseUrl }
  $key = ''
  if ($q.apiKey) { $key = [string]$q.apiKey }
  return [pscustomobject]@{
    enabled    = $enabled
    baseUrl    = $base.TrimEnd('/')
    apiKey     = $key
    source     = $source
    failOpen   = $failOpen
    timeoutSec = $timeout
  }
}

function Get-FeishuWriteMode($cfg) {
  # direct | dual | center
  $mode = 'direct'
  if ($cfg.feishu -and $cfg.feishu.writeMode) {
    $mode = [string]$cfg.feishu.writeMode
  } elseif ($cfg.qingquan -and $cfg.qingquan.enabled) {
    # 启用清泉但未写 writeMode 时，Stage A 默认 dual
    $mode = 'dual'
  }
  $mode = $mode.ToLowerInvariant()
  if ($mode -notin @('direct', 'dual', 'center')) { $mode = 'direct' }
  return $mode
}

function ConvertTo-QingquanIngestItems {
  param(
    [Parameter(Mandatory = $true)] $Rows,
    [Parameter(Mandatory = $true)] [string]$CollectedAt,
    [string]$Currency = 'USD'
  )
  if ([string]::IsNullOrWhiteSpace($Currency)) { $Currency = 'USD' }
  $items = @()
  foreach ($r in @($Rows)) {
    $campaign = [string]$r.campaign
    if (-not $campaign) { continue }
    $storeId = [string]$r.storeId
    $bizDate = [string]$r.date
    $spend = 0; if ($null -ne $r.spend) { $spend = [double]$r.spend }
    $orders = 0; if ($null -ne $r.orders) { $orders = [double]$r.orders }
    $roi = $null; if ($null -ne $r.roi) { $roi = [double]$r.roi }
    $revenue = 0; if ($null -ne $r.revenue) { $revenue = [double]$r.revenue }
    $status = 'success'; if ($r.status) { $status = [string]$r.status }
    $sourceUrl = ''; if ($r.sourceUrl) { $sourceUrl = [string]$r.sourceUrl }
    $storeName = ''; if ($r.store) { $storeName = [string]$r.store }
    $rowCurrency = $Currency
    if ($r.currency) { $rowCurrency = [string]$r.currency }

    $items += [ordered]@{
      platform         = 'tiktok'
      shop_id          = $storeId
      shop_name        = $storeName
      biz_date         = $bizDate
      collected_at     = $CollectedAt
      idempotency_key  = ("tiktok_ads:{0}:{1}:{2}" -f $storeId, $campaign, $bizDate)
      payload          = [ordered]@{
        campaign_name = $campaign
        spend         = $spend
        orders        = $orders
        roi           = $roi
        revenue       = $revenue
        row_status    = $status
        currency      = $rowCurrency
        source_url    = $sourceUrl
      }
      evidence         = [ordered]@{
        source_url = $sourceUrl
      }
    }
  }
  return $items
}

function Send-QingquanIngest {
  param(
    [Parameter(Mandatory = $true)] $Config,
    [Parameter(Mandatory = $true)] $Items,
    [switch]$Quiet
  )
  $q = Get-QingquanConfig $Config
  if (-not $q.enabled) {
    return [pscustomobject]@{ ok = $true; skipped = $true; reason = 'qingquan.disabled'; accepted = 0; duplicated = 0; failed = 0 }
  }
  if (-not $q.apiKey) {
    $msg = 'qingquan.apiKey empty'
    if ($q.failOpen) {
      if (-not $Quiet) { Write-Warning $msg }
      return [pscustomobject]@{ ok = $false; skipped = $false; error = $msg; accepted = 0; duplicated = 0; failed = @($Items).Count }
    }
    throw $msg
  }
  if (@($Items).Count -eq 0) {
    return [pscustomobject]@{ ok = $true; skipped = $true; reason = 'empty-items'; accepted = 0; duplicated = 0; failed = 0 }
  }

  $url = "{0}/api/v1/ingest/{1}" -f $q.baseUrl, $q.source
  $payload = @{ items = @($Items) }
  $json = $payload | ConvertTo-Json -Depth 10 -Compress
  # PS 5.1 ConvertTo-Json 对中文可能转义；UTF8 字节发送
  $bodyBytes = [System.Text.Encoding]::UTF8.GetBytes($json)

  try {
    $resp = Invoke-RestMethod -Method Post -Uri $url -TimeoutSec $q.timeoutSec -ContentType 'application/json; charset=utf-8' -Body $bodyBytes -Headers @{
      'X-Api-Key' = $q.apiKey
    }
    $accepted = 0; $duplicated = 0; $failed = 0
    if ($null -ne $resp.accepted) { $accepted = [int]$resp.accepted }
    if ($null -ne $resp.duplicated) { $duplicated = [int]$resp.duplicated }
    if ($null -ne $resp.failed) { $failed = [int]$resp.failed }
    return [pscustomobject]@{
      ok         = ($failed -eq 0)
      skipped    = $false
      accepted   = $accepted
      duplicated = $duplicated
      failed     = $failed
      resp       = $resp
      error      = $null
    }
  }
  catch {
    $err = [string]$_
    if ($q.failOpen) {
      if (-not $Quiet) { Write-Warning ("qingquan ingest failed (failOpen): {0}" -f $err) }
      return [pscustomobject]@{
        ok         = $false
        skipped    = $false
        accepted   = 0
        duplicated = 0
        failed     = @($Items).Count
        resp       = $null
        error      = $err
      }
    }
    throw
  }
}

function Test-QingquanHealth {
  param([Parameter(Mandatory = $true)] $Config)
  $q = Get-QingquanConfig $Config
  $url = "{0}/health" -f $q.baseUrl
  try {
    $r = Invoke-RestMethod -Method Get -Uri $url -TimeoutSec 10
    return [pscustomobject]@{ ok = ($r.status -eq 'ok'); resp = $r; error = $null }
  }
  catch {
    return [pscustomobject]@{ ok = $false; resp = $null; error = [string]$_ }
  }
}

extension\\background\\service-worker.js.content:
/**
 * Service Worker：消息路由、飞书写入、定时抓取
 */

import { ALARM_NAME, MSG } from '../lib/constants.js';
import {
  getConfig,
  saveConfig,
  getLogs,
  clearLogs,
  getLastResult,
  saveLastResult
} from '../lib/storage.js';
import { log } from '../lib/logger.js';
import {
  normalizeRow,
  filterValidRows,
  resolveBizDate,
  mapStoreName
} from '../scraper/normalize.js';
import { writeRecords, testFeishuConnection } from '../feishu/bitable.js';

const TIKTOK_URL_RE = /tiktok\.com|tiktokglobalshop\.com/i;

// —— 启动：恢复定时 ——
chrome.runtime.onInstalled.addListener(async () => {
  await syncAlarmFromConfig();
  await log('info', '插件已安装/更新');
});

chrome.runtime.onStartup.addListener(async () => {
  await syncAlarmFromConfig();
});

chrome.alarms.onAlarm.addListener(async (alarm) => {
  if (alarm.name !== ALARM_NAME) return;
  await log('info', '定时任务触发，开始抓取');
  try {
    const result = await runFullScrape({ reason: 'schedule' });
    await notify(
      result.ok ? '定时抓取完成' : '定时抓取失败',
      result.ok
        ? `共 ${result.rows?.length || 0} 条，写入 ${result.write?.written ?? 0}`
        : result.error || '未知错误'
    );
  } catch (e) {
    await log('error', '定时抓取异常', { error: String(e.message || e) });
    await notify('定时抓取异常', String(e.message || e));
  }
});

chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
  handleMessage(msg, sender)
    .then(sendResponse)
    .catch((e) => sendResponse({ ok: false, error: String(e.message || e) }));
  return true;
});

async function handleMessage(msg) {
  if (!msg?.type) return { ok: false, error: 'invalid message' };

  switch (msg.type) {
    case MSG.GET_CONFIG:
      return { ok: true, config: await getConfig() };

    case MSG.SAVE_CONFIG: {
      const config = await saveConfig(msg.config || {});
      await syncAlarmFromConfig();
      return { ok: true, config };
    }

    case MSG.GET_LOGS:
      return { ok: true, logs: await getLogs() };

    case MSG.CLEAR_LOGS:
      await clearLogs();
      return { ok: true };

    case MSG.GET_LAST_RESULT:
      return { ok: true, result: await getLastResult() };

    case MSG.TEST_FEISHU:
      try {
        const r = await testFeishuConnection();
        await log('success', '飞书连通性测试成功', r);
        return { ok: true, ...r };
      } catch (e) {
        await log('error', '飞书连通性测试失败', { error: String(e.message || e) });
        return { ok: false, error: String(e.message || e) };
      }

    case MSG.RUN_FULL:
      return runFullScrape({
        reason: msg.reason || 'manual',
        tabId: msg.tabId,
        dryRun: msg.dryRun
      });

    case MSG.WRITE_FEISHU:
      return writeOnly(msg.rows || [], { dryRun: msg.dryRun });

    default:
      return { ok: false, error: `unknown type: ${msg.type}` };
  }
}

/**
 * 完整流程：找 tab → 抓取 → 归一化 → 写飞书
 */
async function runFullScrape({ reason = 'manual', tabId, dryRun } = {}) {
  const config = await getConfig();
  const useDryRun = dryRun != null ? dryRun : config.dryRun;

  let tab;
  try {
    tab = tabId
      ? await chrome.tabs.get(tabId)
      : await findBestTikTokTab();
  } catch {
    tab = null;
  }

  if (!tab?.id) {
    const error =
      '未找到已打开的 TikTok 广告/卖家页面。请在紫鸟店铺窗口中打开广告数据列表后再试。';
    await log('error', error, { reason });
    const result = { ok: false, error, reason };
    await saveLastResult(result);
    return result;
  }

  // 确保 content script 可用
  let scrape;
  try {
    scrape = await sendToTab(tab.id, { type: 'SCRAPE_PAGE', options: { waitMs: 10000 } });
  } catch (e) {
    // 尝试动态注入
    try {
      await chrome.scripting.executeScript({
        target: { tabId: tab.id },
        files: ['content/content.js']
      });
      await sleep(300);
      scrape = await sendToTab(tab.id, { type: 'SCRAPE_PAGE', options: { waitMs: 10000 } });
    } catch (e2) {
      const error = `无法与页面通信: ${e2.message || e.message || e}`;
      await log('error', error, { reason, url: tab.url });
      const result = { ok: false, error, reason, url: tab.url };
      await saveLastResult(result);
      return result;
    }
  }

  if (!scrape?.ok) {
    const error = scrape?.error || '抓取失败';
    await log('error', error, { reason, url: tab.url, source: scrape?.source });
    const result = {
      ok: false,
      error,
      reason,
      url: tab.url,
      scrape
    };
    await saveLastResult(result);
    return result;
  }

  const date = resolveBizDate(config.dateMode, config.customDate);
  const storeName = mapStoreName(
    scrape.storeName,
    config.storeMappings,
    config.defaultStoreName
  );

  const ctx = {
    date,
    storeName,
    storeId: '',
    // 与 TikTok 广告后台一致：广告花费 / 销售额按美金
    currency: scrape.currency || 'USD',
    sourceUrl: scrape.url || tab.url,
    scrapedAt: scrape.scrapedAt || new Date().toISOString()
  };

  const rows = filterValidRows(
    (scrape.rawRows || []).map((r) => normalizeRow(r, ctx))
  );

  if (!rows.length) {
    const error = '抓取到数据但归一化后为空（可能是汇总行或字段未识别）';
    await log('warn', error, { reason, rawCount: scrape.rawRows?.length });
    const result = { ok: false, error, reason, scrape, rows: [] };
    await saveLastResult(result);
    return result;
  }

  let write;
  try {
    write = await writeRecords(rows, { dryRun: useDryRun });
    await log('success', useDryRun ? '干跑抓取成功' : '抓取并写入成功', {
      reason,
      count: rows.length,
      written: write.written,
      dryRun: write.dryRun,
      store: storeName,
      source: scrape.source
    });
  } catch (e) {
    const error = String(e.message || e);
    await log('error', `写入飞书失败: ${error}`, { reason, count: rows.length });
    const result = {
      ok: false,
      error,
      reason,
      rows,
      scrape,
      storeName,
      date
    };
    await saveLastResult(result);
    return result;
  }

  const result = {
    ok: true,
    reason,
    rows,
    write,
    storeName,
    date,
    source: scrape.source,
    url: scrape.url || tab.url,
    dryRun: useDryRun
  };
  await saveLastResult(result);
  return result;
}

async function writeOnly(rows, { dryRun } = {}) {
  try {
    const write = await writeRecords(rows, { dryRun });
    await log('success', dryRun ? '干跑预览写入跳过' : '手动写入成功', {
      written: write.written,
      count: rows.length
    });
    return { ok: true, write };
  } catch (e) {
    await log('error', `写入失败: ${e.message || e}`);
    return { ok: false, error: String(e.message || e) };
  }
}

async function findBestTikTokTab() {
  const tabs = await chrome.tabs.query({});
  const matched = tabs.filter((t) => t.url && TIKTOK_URL_RE.test(t.url));
  if (!matched.length) return null;
  // 优先当前窗口 active
  matched.sort((a, b) => {
    if (a.active && !b.active) return -1;
    if (!a.active && b.active) return 1;
    return (b.lastAccessed || 0) - (a.lastAccessed || 0);
  });
  // 优先 ads / seller / campaign 路径
  const scored = matched.map((t) => {
    let s = 0;
    const u = t.url.toLowerCase();
    if (u.includes('ads')) s += 3;
    if (u.includes('seller')) s += 2;
    if (u.includes('campaign') || u.includes('shop-ads') || u.includes('gmv')) s += 4;
    if (t.active) s += 1;
    return { t, s };
  });
  scored.sort((a, b) => b.s - a.s);
  return scored[0].t;
}

function sendToTab(tabId, message) {
  return new Promise((resolve, reject) => {
    chrome.tabs.sendMessage(tabId, message, (response) => {
      if (chrome.runtime.lastError) {
        reject(new Error(chrome.runtime.lastError.message));
        return;
      }
      resolve(response);
    });
  });
}

async function syncAlarmFromConfig() {
  const config = await getConfig();
  await chrome.alarms.clear(ALARM_NAME);
  if (!config.schedule?.enabled) {
    await log('info', '定时任务已关闭');
    return;
  }
  const hour = Number(config.schedule.hour) || 7;
  const minute = Number(config.schedule.minute) || 30;
  // when: 下一次该时刻；periodInMinutes: 每天
  const when = nextAlarmTime(hour, minute);
  await chrome.alarms.create(ALARM_NAME, {
    when,
    periodInMinutes: 24 * 60
  });
  await log('info', `定时任务已设置: 每天 ${pad(hour)}:${pad(minute)}`, {
    when: new Date(when).toISOString()
  });
}

function nextAlarmTime(hour, minute) {
  const now = new Date();
  const next = new Date();
  next.setHours(hour, minute, 0, 0);
  if (next.getTime() <= now.getTime()) {
    next.setDate(next.getDate() + 1);
  }
  return next.getTime();
}

function pad(n) {
  return String(n).padStart(2, '0');
}

async function notify(title, message) {
  try {
    if (!chrome.notifications?.create) return;
    await chrome.notifications.create({
      type: 'basic',
      iconUrl: 'icons/icon128.png',
      title,
      message: String(message).slice(0, 200)
    });
  } catch {
    /* 部分环境无 notifications 权限也可忽略 */
  }
}

function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

extension\\scraper\\normalize.js.content:
/**
 * 字段归一化：统一为业务 5 字段 + 元数据
 */

/**
 * 从单元格文本识别币种（$ / £ / € 等）
 * @param {unknown} text
 * @returns {'USD'|'GBP'|'EUR'|'CNY'|null}
 */
export function detectCurrency(text) {
  const s = String(text ?? '');
  if (/[£]|GBP|英镑/i.test(s)) return 'GBP';
  if (/[€]|EUR|欧元/i.test(s)) return 'EUR';
  if (/[¥￥]|CNY|RMB|元/i.test(s) && !/\$/.test(s)) return 'CNY';
  if (/\$|USD|美金|美元/i.test(s)) return 'USD';
  return null;
}

/**
 * 从字符串解析数字（去掉货币符号、千分位、百分号）
 * 金额按美金口径使用；符号仅用于识别币种，不改变数值本身。
 * @param {unknown} value
 * @returns {number|null}
 */
export function parseNumber(value) {
  if (value == null || value === '') return null;
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  let s = String(value).trim();
  if (!s || s === '-' || s === '—') return null;
  s = s
    .replace(/[,\s]/g, '')
    .replace(/[¥$€£￥]/g, '')
    .replace(/USD|GBP|EUR|CNY|RMB|美金|美元|英镑|欧元/gi, '')
    .replace(/%/g, '');
  // 括号负数 (1.2) → -1.2
  const paren = s.match(/^\((.+)\)$/);
  if (paren) s = `-${paren[1]}`;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

/**
 * @param {string} text
 * @returns {string}
 */
export function cleanText(text) {
  return String(text ?? '')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * 解析业务日期 YYYY-MM-DD
 * @param {'yesterday'|'today'|'custom'} mode
 * @param {string} [customDate]
 */
export function resolveBizDate(mode, customDate) {
  if (mode === 'custom' && customDate) {
    return customDate.slice(0, 10);
  }
  const d = new Date();
  if (mode === 'yesterday') {
    d.setDate(d.getDate() - 1);
  }
  return formatDateLocal(d);
}

export function formatDateLocal(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

/**
 * 应用店铺名映射
 * @param {string} detected
 * @param {{alias:string,name:string}[]} mappings
 * @param {string} [fallback]
 */
export function mapStoreName(detected, mappings = [], fallback = '') {
  const raw = cleanText(detected || '');
  if (!raw && fallback) return fallback;
  for (const m of mappings) {
    if (!m?.alias) continue;
    if (raw.toLowerCase().includes(String(m.alias).toLowerCase()) ||
        String(m.alias).toLowerCase().includes(raw.toLowerCase())) {
      return m.name || m.alias;
    }
  }
  return raw || fallback || '未知店铺';
}

/**
 * 将原始行归一化为标准记录
 * @param {object} row
 * @param {object} ctx
 */
export function normalizeRow(row, ctx = {}) {
  const campaign = cleanText(row.campaign ?? row.name ?? '');
  const spend = parseNumber(row.spend ?? row.cost);
  const orders = parseNumber(row.orders ?? row.units ?? row.sales_count);
  const roi = parseNumber(row.roi ?? row.roas);
  const revenue = parseNumber(row.revenue ?? row.gmv ?? row.income);
  // 与广告后台一致：落库单位为美金 USD
  const currency = cleanText(row.currency || ctx.currency || 'USD').toUpperCase() || 'USD';

  const filled = [campaign, spend, orders, roi, revenue].filter(
    (v) => v !== null && v !== ''
  ).length;

  let status = 'success';
  if (!campaign && filled === 0) status = 'error';
  else if (filled < 4) status = 'partial';

  return {
    date: ctx.date || resolveBizDate('yesterday'),
    store: ctx.storeName || '未知店铺',
    storeId: ctx.storeId || '',
    campaign,
    spend: spend ?? 0,
    orders: orders ?? 0,
    roi: roi ?? 0,
    revenue: revenue ?? 0,
    currency,
    scrapedAt: ctx.scrapedAt || new Date().toISOString(),
    sourceUrl: ctx.sourceUrl || '',
    status
  };
}

/**
 * 过滤空行 / 汇总行
 * @param {ReturnType<typeof normalizeRow>[]} rows
 */
export function filterValidRows(rows) {
  return rows.filter((r) => {
    if (!r) return false;
    if (!r.campaign) return false;
    const lower = r.campaign.toLowerCase();
    if (['total', '合计', '总计', '汇总', 'summary', 'all'].includes(lower)) {
      return false;
    }
    return true;
  });
}

